// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _target, uint256 _value) public {
        vm.assume(_target != address(0));
        vm.assume(_value <= address(c).balance);
        vm.assume(c.owner() == address(this));

        uint256 ownerBalanceBefore = address(this).balance;
        uint256 contractBalanceBefore = address(c).balance;

        c.sendMoney(_target, _value);

        uint256 ownerBalanceAfter = address(this).balance;
        uint256 contractBalanceAfter = address(c).balance;

        assertTrue(ownerBalanceAfter == ownerBalanceBefore + _value && contractBalanceAfter == contractBalanceBefore - _value);
    }
}

