pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _target, uint256 _value) public {
        vm.assume(_target != address(c));
        vm.assume(_value > 0 && _value <= address(c).balance);
        uint256 balanceBefore = address(c).balance;
        vm.prank(c.owner());
        c.sendMoney(_target, _value);
        assertTrue(address(c).balance == balanceBefore - _value);
    }
}

